files.dsl/regions/cn_dsl_v1/rules/R-010-PARSE-:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-010-PARSE-BIRTH-YEAR",
  "name": "解析出生年份（支持“73年=1973”）",
  "module": "normalization",
  "status": "published",
  "priority": 10,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "内置 parse_birth_year：两位数>=30按1900+；两位数<30默认2000+，若上下文存在年龄>=30则按1900+（可在内置函数中实现）。",
  "inputs": [
    {
      "key": "user.basic.birth_year",
      "type": "number",
      "required": false,
      "desc": "出生年份（若用户已填）"
    },
    {
      "key": "user.basic.birth_year_text",
      "type": "string",
      "required": false,
      "desc": "用户输入的出生年份文本（如“73年”“1973”“73”）"
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_provided",
        "when": {
          "!=": [
            {
              "var": "user.basic.birth_year"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.normalization.birth_year_source",
              "value": "provided"
            }
          ]
        }
      },
      {
        "row_id": "row_2_parse_text",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.basic.birth_year"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "user.basic.birth_year_text"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "call",
              "fn": "parse_birth_year",
              "args": {
                "text": {
                  "var": "user.basic.birth_year_text"
                }
              },
              "into": "user.basic.birth_year"
            },
            {
              "type": "set",
              "path": "calc.normalization.birth_year_source",
              "value": "parsed_from_text"
            }
          ]
        }
      },
      {
        "row_id": "row_3_missing",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.basic.birth_year"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "user.basic.birth_year_text"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-BIRTH-YEAR",
                "text": "请提供出生年份（例如：1973，或写“73年”代表1973年）",
                "field": "user.basic.birth_year"
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "user.basic.birth_year",
      "type": "number",
      "desc": "标准化后的出生年份"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean",
      "desc": "是否需要 Agent 补问"
    },
    {
      "key": "calc.agent_questions",
      "type": "array",
      "desc": "需要追问的问题列表（累加）"
    }
  ],
  "examples": [
    {
      "name": "73年 -> 1973",
      "input": {
        "user": {
          "basic": {
            "birth_year": null,
            "birth_year_text": "73年"
          }
        }
      },
      "expected": {
        "user": {
          "basic": {
            "birth_year": 1973
          }
        },
        "calc": {
          "normalization": {
            "birth_year_source": "parsed_from_text"
          }
        }
      }
    },
    {
      "name": "1973 -> 1973",
      "input": {
        "user": {
          "basic": {
            "birth_year": null,
            "birth_year_text": "1973"
          }
        }
      },
      "expected": {
        "user": {
          "basic": {
            "birth_year": 1973
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-011-BUILD-:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-011-BUILD-BIRTH-DATE",
  "name": "组装出生日期（年/月/日 -> YYYY-MM-DD）",
  "module": "normalization",
  "status": "published",
  "priority": 11,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "make_date 需校验日期合法性；非法日期应 emit_warning 并 needs_agent。",
  "inputs": [
    {
      "key": "user.basic.birth_date",
      "type": "date",
      "required": false,
      "desc": "出生日期"
    },
    {
      "key": "user.basic.birth_year",
      "type": "number",
      "required": false,
      "desc": "出生年份（已标准化）"
    },
    {
      "key": "user.basic.birth_month",
      "type": "number",
      "required": false,
      "desc": "出生月份(1-12)"
    },
    {
      "key": "user.basic.birth_day",
      "type": "number",
      "required": false,
      "desc": "出生日期(1-31)"
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_already_have",
        "when": {
          "!=": [
            {
              "var": "user.basic.birth_date"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.normalization.birth_date_source",
              "value": "provided"
            }
          ]
        }
      },
      {
        "row_id": "row_2_build",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.basic.birth_date"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "user.basic.birth_year"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "user.basic.birth_month"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "user.basic.birth_day"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "call",
              "fn": "make_date",
              "args": {
                "year": {
                  "var": "user.basic.birth_year"
                },
                "month": {
                  "var": "user.basic.birth_month"
                },
                "day": {
                  "var": "user.basic.birth_day"
                }
              },
              "into": "user.basic.birth_date"
            },
            {
              "type": "set",
              "path": "calc.normalization.birth_date_source",
              "value": "built_from_fields"
            }
          ]
        }
      },
      {
        "row_id": "row_2b_default_month_day",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.basic.birth_date"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "user.basic.birth_year"
                },
                null
              ]
            },
            {
              "or": [
                {
                  "==": [
                    {
                      "var": "user.basic.birth_month"
                    },
                    null
                  ]
                },
                {
                  "==": [
                    {
                      "var": "user.basic.birth_day"
                    },
                    null
                  ]
                }
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "user.basic.birth_month",
              "value": {
                "if": [
                  {
                    "==": [
                      {
                        "var": "user.basic.birth_month"
                      },
                      null
                    ]
                  },
                  1,
                  {
                    "var": "user.basic.birth_month"
                  }
                ]
              }
            },
            {
              "type": "set",
              "path": "user.basic.birth_day",
              "value": {
                "if": [
                  {
                    "==": [
                      {
                        "var": "user.basic.birth_day"
                      },
                      null
                    ]
                  },
                  1,
                  {
                    "var": "user.basic.birth_day"
                  }
                ]
              }
            },
            {
              "type": "call",
              "fn": "make_date",
              "args": {
                "year": {
                  "var": "user.basic.birth_year"
                },
                "month": {
                  "var": "user.basic.birth_month"
                },
                "day": {
                  "var": "user.basic.birth_day"
                }
              },
              "into": "user.basic.birth_date"
            },
            {
              "type": "set",
              "path": "calc.normalization.birth_date_source",
              "value": "defaulted_month_day"
            },
            {
              "type": "emit_caveat",
              "value": {
                "caveat_id": "C-BIRTH-MONTH-DEFAULT",
                "text": "出生月份未提供，默认为1月。实际退休日期可能相差数月，建议补充准确出生月份。",
                "confidence": "medium"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_4_missing_year",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.basic.birth_date"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "user.basic.birth_year"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-BIRTH-YEAR",
                "text": "请提供出生年份（例如：1973）",
                "field": "user.basic.birth_year"
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "user.basic.birth_date",
      "type": "date",
      "desc": "标准化出生日期"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "有年/月/日可组装",
      "input": {
        "user": {
          "basic": {
            "birth_date": null,
            "birth_year": 1973,
            "birth_month": 5,
            "birth_day": 12
          }
        }
      },
      "expected": {
        "user": {
          "basic": {
            "birth_date": "1973-05-12"
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-012-NORMAL:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-012-NORMALIZE-GENDER",
  "name": "标准化性别输入",
  "module": "normalization",
  "status": "published",
  "priority": 12,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "normalize_gender：支持 男/女/男性/女性/m/f 等映射；无法识别则 needs_agent + question。",
  "inputs": [
    {
      "key": "user.basic.gender",
      "type": "string",
      "required": false,
      "desc": "性别（可能是“男/女/male/female”）"
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_already_norm",
        "when": {
          "or": [
            {
              "==": [
                {
                  "var": "user.basic.gender"
                },
                "male"
              ]
            },
            {
              "==": [
                {
                  "var": "user.basic.gender"
                },
                "female"
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.normalization.gender_source",
              "value": "provided_normalized"
            }
          ]
        }
      },
      {
        "row_id": "row_2_try_normalize",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.basic.gender"
                },
                null
              ]
            },
            {
              "!": {
                "or": [
                  {
                    "==": [
                      {
                        "var": "user.basic.gender"
                      },
                      "male"
                    ]
                  },
                  {
                    "==": [
                      {
                        "var": "user.basic.gender"
                      },
                      "female"
                    ]
                  }
                ]
              }
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "call",
              "fn": "normalize_gender",
              "args": {
                "text": {
                  "var": "user.basic.gender"
                }
              },
              "into": "user.basic.gender"
            },
            {
              "type": "set",
              "path": "calc.normalization.gender_source",
              "value": "normalized_from_text"
            }
          ]
        }
      },
      {
        "row_id": "row_3_missing",
        "when": {
          "==": [
            {
              "var": "user.basic.gender"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-GENDER",
                "text": "请确认性别（男/女）。退休年龄与补贴资格会因此不同。",
                "field": "user.basic.gender"
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "user.basic.gender",
      "type": "string"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "男 -> male",
      "input": {
        "user": {
          "basic": {
            "gender": "男"
          }
        }
      },
      "expected": {
        "user": {
          "basic": {
            "gender": "male"
          }
        }
      }
    },
    {
      "name": "female 保持",
      "input": {
        "user": {
          "basic": {
            "gender": "female"
          }
        }
      },
      "expected": {
        "user": {
          "basic": {
            "gender": "female"
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-020-FEMALE:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-020-FEMALE-RETIRE-TYPE",
  "name": "女性50/55口径确认（女工50 / 女干部55）",
  "module": "retirement",
  "status": "published",
  "priority": 20,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "",
  "inputs": [
    {
      "key": "user.basic.gender",
      "type": "string",
      "required": true,
      "desc": "male/female"
    },
    {
      "key": "user.basic.female_retire_type",
      "type": "string",
      "required": false,
      "desc": "worker50/cadre55/unknown"
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_male_set_na",
        "when": {
          "==": [
            {
              "var": "user.basic.gender"
            },
            "male"
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "user.basic.female_retire_type",
              "value": "na"
            }
          ]
        }
      },
      {
        "row_id": "row_2_female_known",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.basic.gender"
                },
                "female"
              ]
            },
            {
              "in": [
                {
                  "var": "user.basic.female_retire_type"
                },
                [
                  "worker50",
                  "cadre55"
                ]
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.retirement.female_retire_type_status",
              "value": "confirmed"
            }
          ]
        }
      },
      {
        "row_id": "row_3_female_unknown",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.basic.gender"
                },
                "female"
              ]
            },
            {
              "!": {
                "in": [
                  {
                    "var": "user.basic.female_retire_type"
                  },
                  [
                    "worker50",
                    "cadre55"
                  ]
                ]
              }
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-FEMALE-RETIRE-TYPE",
                "text": "请确认女性退休口径：女工一般50岁、女干部/管理岗一般55岁（以你本人档案/参保口径为准）。",
                "field": "user.basic.female_retire_type"
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "user.basic.female_retire_type",
      "type": "string"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "女性未填口径 -> 追问",
      "input": {
        "user": {
          "basic": {
            "gender": "female",
            "female_retire_type": null
          }
        }
      },
      "expected": {
        "calc": {
          "needs_agent": true
        }
      }
    },
    {
      "name": "男性 -> na",
      "input": {
        "user": {
          "basic": {
            "gender": "male"
          }
        }
      },
      "expected": {
        "user": {
          "basic": {
            "female_retire_type": "na"
          }
        }
      }
    }
  ],
  "evidence": [
    {
      "document_id": "DOC-CN-NPC-DELAYED-RETIREMENT-2024",
      "jurisdiction_code": "CN",
      "title": "全国人民代表大会常务委员会关于实施渐进式延迟法定退休年龄的决定",
      "authority": "全国人民代表大会常务委员会",
      "official_url": "https://www.mohrss.gov.cn/SYrlzyhshbzb/ztzl/zt202409/qwfb/202409/t20240913_525781.html",
      "fetched_at": "2026-09-05T13:37:42.739Z",
      "content_sha256": "69a02418f3ce5fbc6276135990e62731cfb6ae7c0b1524c3f2f855651ffa7d9b",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/CN/DOC-CN-NPC-DELAYED-RETIREMENT-2024/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "article",
        "reference": "决定第一条"
      },
      "excerpt": "用十五年时间，逐步将男职工的法定退休年龄从原六十周岁延迟至六十三周岁，将女职工的法定退休年龄从原五十周岁、五十五周岁分别延迟至五十五周岁、五十八周岁。"
    }
  ],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-110-LOOKUP:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-110-LOOKUP-LEGAL-RETIRE-AGE",
  "name": "查表计算法定退休年龄（参数表驱动）",
  "module": "retirement",
  "status": "published",
  "priority": 110,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "本规则本身不内置延迟退休算法；由参数表/外部服务决定退休年龄。这样才能满足“政策更新不改代码”。",
  "inputs": [
    {
      "key": "user.basic.gender",
      "type": "string",
      "required": true
    },
    {
      "key": "user.basic.female_retire_type",
      "type": "string",
      "required": true
    },
    {
      "key": "user.basic.birth_year",
      "type": "number",
      "required": true
    }
  ],
  "parameter_refs": [
    {
      "param_id": "T-RETIREMENT-AGE-LOOKUP",
      "purpose": "退休年龄映射表"
    }
  ],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_missing_inputs",
        "when": {
          "or": [
            {
              "==": [
                {
                  "var": "user.basic.gender"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "user.basic.female_retire_type"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "user.basic.birth_year"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-RETIRE-INPUTS",
                "text": "计算退休年龄需要：性别、女性50/55口径、出生年份。请补齐。"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_lookup",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.basic.gender"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "user.basic.female_retire_type"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "user.basic.birth_year"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "lookup",
              "table_param_id": "T-RETIREMENT-AGE-LOOKUP",
              "key": {
                "gender": {
                  "var": "user.basic.gender"
                },
                "female_retire_type": {
                  "var": "user.basic.female_retire_type"
                },
                "birth_year": {
                  "var": "user.basic.birth_year"
                }
              },
              "into": "calc.retirement._table_override",
              "into_map": {
                "legal_retire_age_years": "calc.retirement.legal_retire_age_years",
                "legal_retire_age_months": "calc.retirement.legal_retire_age_months",
                "original_retire_age_years": "calc.retirement.original_retire_age_years"
              }
            },
            {
              "type": "call",
              "fn": "compute_delayed_retire_age",
              "args": {
                "gender": {
                  "var": "user.basic.gender"
                },
                "female_retire_type": {
                  "var": "user.basic.female_retire_type"
                },
                "birth_year": {
                  "var": "user.basic.birth_year"
                },
                "birth_month": {
                  "var": "user.basic.birth_month"
                }
              },
              "into": "calc.retirement._algo_result"
            },
            {
              "type": "set",
              "path": "calc.retirement.legal_retire_age_years",
              "value": {
                "if": [
                  {
                    "!=": [
                      {
                        "var": "calc.retirement.legal_retire_age_years"
                      },
                      null
                    ]
                  },
                  {
                    "var": "calc.retirement.legal_retire_age_years"
                  },
                  {
                    "var": "calc.retirement._algo_result.legal_retire_age_years"
                  }
                ]
              }
            },
            {
              "type": "set",
              "path": "calc.retirement.legal_retire_age_months",
              "value": {
                "if": [
                  {
                    "!=": [
                      {
                        "var": "calc.retirement.legal_retire_age_months"
                      },
                      null
                    ]
                  },
                  {
                    "var": "calc.retirement.legal_retire_age_months"
                  },
                  {
                    "var": "calc.retirement._algo_result.legal_retire_age_months"
                  }
                ]
              }
            },
            {
              "type": "set",
              "path": "calc.retirement.original_retire_age_years",
              "value": {
                "if": [
                  {
                    "!=": [
                      {
                        "var": "calc.retirement.original_retire_age_years"
                      },
                      null
                    ]
                  },
                  {
                    "var": "calc.retirement.original_retire_age_years"
                  },
                  {
                    "var": "calc.retirement._algo_result.original_retire_age_years"
                  }
                ]
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.retirement.legal_retire_age_years",
      "type": "number",
      "desc": "法定退休年龄(岁)"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
