files.dsl/regions/cn_dsl_v1/rules/R-115-FLEXIB:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-115-FLEXIBLE-RETIREMENT",
  "name": "弹性退休年龄调整",
  "module": "retirement",
  "status": "published",
  "priority": 115,
  "effective_from": "2025-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "2025年弹性退休制度：可提前最多3年（不低于原法定年龄），或延迟最多3年。基于 retire_preference 字段调整。",
  "inputs": [
    {
      "key": "user.basic.retire_preference",
      "type": "string",
      "required": false,
      "desc": "退休偏好：earliest/standard/latest",
      "enum": [
        "earliest",
        "standard",
        "latest"
      ]
    },
    {
      "key": "calc.retirement.legal_retire_age_years",
      "type": "number",
      "required": true
    },
    {
      "key": "calc.retirement.legal_retire_age_months",
      "type": "number",
      "required": true
    },
    {
      "key": "calc.retirement.original_retire_age_years",
      "type": "number",
      "required": true
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_no_preference",
        "when": {
          "or": [
            {
              "==": [
                {
                  "var": "user.basic.retire_preference"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "user.basic.retire_preference"
                },
                "standard"
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.retirement.flex_adjusted",
              "value": false
            },
            {
              "type": "set",
              "path": "calc.retirement.flex_preference",
              "value": "standard"
            }
          ]
        }
      },
      {
        "row_id": "row_2_earliest",
        "when": {
          "==": [
            {
              "var": "user.basic.retire_preference"
            },
            "earliest"
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.retirement.flex_adjusted",
              "value": true
            },
            {
              "type": "set",
              "path": "calc.retirement.flex_preference",
              "value": "earliest"
            },
            {
              "type": "set",
              "path": "calc.retirement._earliest_total_months",
              "value": {
                "max": [
                  {
                    "*": [
                      {
                        "var": "calc.retirement.original_retire_age_years"
                      },
                      12
                    ]
                  },
                  {
                    "-": [
                      {
                        "+": [
                          {
                            "*": [
                              {
                                "var": "calc.retirement.legal_retire_age_years"
                              },
                              12
                            ]
                          },
                          {
                            "var": "calc.retirement.legal_retire_age_months"
                          }
                        ]
                      },
                      36
                    ]
                  }
                ]
              }
            },
            {
              "type": "set",
              "path": "calc.retirement.legal_retire_age_years",
              "value": {
                "floor": [
                  {
                    "/": [
                      {
                        "var": "calc.retirement._earliest_total_months"
                      },
                      12
                    ]
                  }
                ]
              }
            },
            {
              "type": "set",
              "path": "calc.retirement.legal_retire_age_months",
              "value": {
                "%": [
                  {
                    "var": "calc.retirement._earliest_total_months"
                  },
                  12
                ]
              }
            }
          ]
        }
      },
      {
        "row_id": "row_3_latest",
        "when": {
          "==": [
            {
              "var": "user.basic.retire_preference"
            },
            "latest"
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.retirement.flex_adjusted",
              "value": true
            },
            {
              "type": "set",
              "path": "calc.retirement.flex_preference",
              "value": "latest"
            },
            {
              "type": "set",
              "path": "calc.retirement._latest_total_months",
              "value": {
                "+": [
                  {
                    "*": [
                      {
                        "var": "calc.retirement.legal_retire_age_years"
                      },
                      12
                    ]
                  },
                  {
                    "var": "calc.retirement.legal_retire_age_months"
                  },
                  36
                ]
              }
            },
            {
              "type": "set",
              "path": "calc.retirement.legal_retire_age_years",
              "value": {
                "floor": [
                  {
                    "/": [
                      {
                        "var": "calc.retirement._latest_total_months"
                      },
                      12
                    ]
                  }
                ]
              }
            },
            {
              "type": "set",
              "path": "calc.retirement.legal_retire_age_months",
              "value": {
                "%": [
                  {
                    "var": "calc.retirement._latest_total_months"
                  },
                  12
                ]
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.retirement.legal_retire_age_years",
      "type": "number"
    },
    {
      "key": "calc.retirement.legal_retire_age_months",
      "type": "number"
    },
    {
      "key": "calc.retirement.flex_adjusted",
      "type": "boolean"
    },
    {
      "key": "calc.retirement.flex_preference",
      "type": "string"
    }
  ],
  "examples": [
    {
      "name": "标准退休（无偏好）不调整",
      "input": {
        "user": {
          "basic": {
            "retire_preference": "standard"
          }
        },
        "calc": {
          "retirement": {
            "legal_retire_age_years": 61,
            "legal_retire_age_months": 6,
            "original_retire_age_years": 60
          }
        }
      },
      "expected": {
        "calc": {
          "retirement": {
            "legal_retire_age_years": 61,
            "legal_retire_age_months": 6,
            "flex_adjusted": false
          }
        }
      }
    },
    {
      "name": "最早退休 - 男1970 delayed 61y6m -> max(60*12, 61*12+6-36) = max(720, 702) = 720 -> 60y0m",
      "input": {
        "user": {
          "basic": {
            "retire_preference": "earliest"
          }
        },
        "calc": {
          "retirement": {
            "legal_retire_age_years": 61,
            "legal_retire_age_months": 6,
            "original_retire_age_years": 60
          }
        }
      },
      "expected": {
        "calc": {
          "retirement": {
            "legal_retire_age_years": 60,
            "legal_retire_age_months": 0,
            "flex_adjusted": true
          }
        }
      }
    }
  ],
  "evidence": [
    {
      "document_id": "DOC-CN-NPC-DELAYED-RETIREMENT-2024",
      "jurisdiction_code": "CN",
      "title": "全国人民代表大会常务委员会关于实施渐进式延迟法定退休年龄的决定",
      "authority": "全国人民代表大会常务委员会",
      "official_url": "https://www.mohrss.gov.cn/SYrlzyhshbzb/ztzl/zt202409/qwfb/202409/t20240913_525781.html",
      "fetched_at": "2026-09-05T13:37:42.739Z",
      "content_sha256": "69a02418f3ce5fbc6276135990e62731cfb6ae7c0b1524c3f2f855651ffa7d9b",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/CN/DOC-CN-NPC-DELAYED-RETIREMENT-2024/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "article",
        "reference": "国务院办法第三条"
      },
      "excerpt": "职工达到最低缴费年限，可以自愿选择弹性提前退休，提前时间最长不超过三年，且退休年龄不得低于女职工五十周岁、五十五周岁及男职工六十周岁的原法定退休年龄。职工达到法定退休年龄，所在单位与职工协商一致的，可以弹性延迟退休，延迟时间最长不超过三年。"
    }
  ],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-120-COMPUT:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-120-COMPUTE-RETIRE-DATE",
  "name": "计算法定退休日期（出生日期 + 退休年龄）",
  "module": "retirement",
  "status": "published",
  "priority": 120,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "date_add_years 的实现需考虑当月退休、待遇起算月等地区口径；建议返回 retire_month（YYYY-MM）供后续规则使用。",
  "inputs": [
    {
      "key": "user.basic.birth_date",
      "type": "date",
      "required": true
    },
    {
      "key": "calc.retirement.legal_retire_age_years",
      "type": "number",
      "required": true
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_missing",
        "when": {
          "or": [
            {
              "==": [
                {
                  "var": "user.basic.birth_date"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "calc.retirement.legal_retire_age_years"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-RETIRE-DATE",
                "text": "计算退休日期需要出生日期（年/月/日）与退休年龄。请补齐出生月日，或上传参保档案截图。",
                "field": "user.basic.birth_date"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_compute",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.basic.birth_date"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.retirement.legal_retire_age_years"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "call",
              "fn": "date_add_years_months",
              "args": {
                "date": {
                  "var": "user.basic.birth_date"
                },
                "years": {
                  "var": "calc.retirement.legal_retire_age_years"
                },
                "months": {
                  "var": "calc.retirement.legal_retire_age_months"
                }
              },
              "into": "calc.retirement.legal_retire_date"
            },
            {
              "type": "call",
              "fn": "date_year",
              "args": {
                "date": {
                  "var": "calc.retirement.legal_retire_date"
                }
              },
              "into": "calc.retirement.legal_retire_year"
            },
            {
              "type": "call",
              "fn": "date_month",
              "args": {
                "date": {
                  "var": "calc.retirement.legal_retire_date"
                }
              },
              "into": "calc.retirement.legal_retire_month"
            },
            {
              "type": "call",
              "fn": "date_diff_months",
              "args": {
                "from": {
                  "var": "calc._today"
                },
                "to": {
                  "var": "calc.retirement.legal_retire_date"
                }
              },
              "into": "calc.retirement.months_to_legal_retire"
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.retirement.legal_retire_date",
      "type": "date"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    },
    {
      "key": "calc.retirement.legal_retire_year",
      "type": "number"
    },
    {
      "key": "calc.retirement.legal_retire_month",
      "type": "number"
    }
  ],
  "examples": [
    {
      "name": "1973-05-12 男 60 -> 2033-05-12",
      "input": {
        "user": {
          "basic": {
            "birth_date": "1973-05-12"
          }
        },
        "calc": {
          "retirement": {
            "legal_retire_age_years": 60
          }
        }
      },
      "expected": {
        "calc": {
          "retirement": {
            "legal_retire_date": "2033-05-12",
            "legal_retire_year": 2033,
            "legal_retire_month": 5
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-200-MIN-PE:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-200-MIN-PENSION-YEARS",
  "name": "按退休年份查最低养老缴费年限（参数时间线）",
  "module": "pension",
  "status": "published",
  "priority": 200,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "该时间线为可配置参数：如政策调整，只需在 Admin 中新增版本/修正 rows，无需改代码。",
  "inputs": [
    {
      "key": "calc.retirement.legal_retire_year",
      "type": "number",
      "required": true
    }
  ],
  "parameter_refs": [
    {
      "param_id": "T-MIN-PENSION-YEARS-BY-RETIRE-YEAR",
      "purpose": "最低缴费年限时间线"
    }
  ],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_missing",
        "when": {
          "==": [
            {
              "var": "calc.retirement.legal_retire_year"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-RETIRE-YEAR",
                "text": "缺少退休年份，无法判断最低缴费年限（15/16/…/20年）。",
                "field": "calc.retirement.legal_retire_year"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_lookup",
        "when": {
          "!=": [
            {
              "var": "calc.retirement.legal_retire_year"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "lookup",
              "table_param_id": "T-MIN-PENSION-YEARS-BY-RETIRE-YEAR",
              "key": {
                "retire_year": {
                  "var": "calc.retirement.legal_retire_year"
                }
              },
              "into": "calc.pension.min_years_required"
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.pension.min_years_required",
      "type": "number",
      "desc": "最低养老缴费年限(年)"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "退休年份2029 -> 15年",
      "input": {
        "calc": {
          "retirement": {
            "legal_retire_year": 2029
          }
        }
      },
      "expected": {
        "calc": {
          "pension": {
            "min_years_required": 15
          }
        }
      }
    },
    {
      "name": "退休年份2036 -> 18.5年",
      "input": {
        "calc": {
          "retirement": {
            "legal_retire_year": 2036
          }
        }
      },
      "expected": {
        "calc": {
          "pension": {
            "min_years_required": 18.5
          }
        }
      }
    }
  ],
  "evidence": [
    {
      "document_id": "DOC-CN-SOCIAL-INSURANCE-LAW",
      "jurisdiction_code": "CN",
      "title": "中华人民共和国社会保险法（2018修正）",
      "authority": "全国人民代表大会常务委员会",
      "official_url": "https://www.mohrss.gov.cn/xxgk2020/fdzdgknr/zcfg/fl/202011/t20201102_394629.html",
      "fetched_at": "2026-09-05T13:38:56.250Z",
      "content_sha256": "b69d5d490f9b6b70394dfb670c2e1a0a959f306e70380bb678ee4866f947d464",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/CN/DOC-CN-SOCIAL-INSURANCE-LAW/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "article",
        "reference": "第十六条"
      },
      "excerpt": "参加基本养老保险的个人，达到法定退休年龄时累计缴费满十五年的，按月领取基本养老金。"
    },
    {
      "document_id": "DOC-CN-NPC-DELAYED-RETIREMENT-2024",
      "jurisdiction_code": "CN",
      "title": "全国人民代表大会常务委员会关于实施渐进式延迟法定退休年龄的决定",
      "authority": "全国人民代表大会常务委员会",
      "official_url": "https://www.mohrss.gov.cn/SYrlzyhshbzb/ztzl/zt202409/qwfb/202409/t20240913_525781.html",
