}

files.dsl/regions/cn_dsl_v1/rules/R-210-PENSIO:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-210-PENSION-GAP",
  "name": "计算养老缴费年限缺口（以月计）",
  "module": "pension",
  "status": "published",
  "priority": 210,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "gap_years_ceil 仅用于展示；实际补缴/续缴按月规划。",
  "inputs": [
    {
      "key": "user.social.pension_contrib_months",
      "type": "number",
      "required": true,
      "desc": "养老累计缴费月数"
    },
    {
      "key": "calc.pension.min_years_required",
      "type": "number",
      "required": true,
      "desc": "最低养老缴费年限(年)"
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_missing",
        "when": {
          "or": [
            {
              "==": [
                {
                  "var": "user.social.pension_contrib_months"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "calc.pension.min_years_required"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-PENSION-MONTHS",
                "text": "请提供养老累计缴费月数（可从随申办/社保查询导出）。",
                "field": "user.social.pension_contrib_months"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_compute",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.social.pension_contrib_months"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.pension.min_years_required"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.pension.gap_months",
              "value": {
                "max": [
                  0,
                  {
                    "-": [
                      {
                        "*": [
                          {
                            "var": "calc.pension.min_years_required"
                          },
                          12
                        ]
                      },
                      {
                        "var": "user.social.pension_contrib_months"
                      }
                    ]
                  }
                ]
              }
            },
            {
              "type": "set",
              "path": "calc.pension.gap_years_ceil",
              "value": {
                "ceil": [
                  {
                    "/": [
                      {
                        "var": "calc.pension.gap_months"
                      },
                      12
                    ]
                  }
                ]
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.pension.gap_months",
      "type": "number"
    },
    {
      "key": "calc.pension.gap_years_ceil",
      "type": "number"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "已缴14年(168月)，要求15年(180月) -> 缺12月",
      "input": {
        "user": {
          "social": {
            "pension_contrib_months": 168
          }
        },
        "calc": {
          "pension": {
            "min_years_required": 15
          }
        }
      },
      "expected": {
        "calc": {
          "pension": {
            "gap_months": 12,
            "gap_years_ceil": 1
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-220-MEDICA:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-220-MEDICAL-LIFETIME-GAP",
  "name": "计算医保终身待遇年限缺口（性别区分）",
  "module": "medical_insurance",
  "status": "published",
  "priority": 220,
  "effective_from": "2025-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "国家框架（社会保险法第二十七条）：达到法定退休年龄时累计缴费达到国家规定年限的，退休后不再缴纳基本医疗保险费。国家规定年限的具体年数由参保地（统筹地区）规定，通过地区参数 P-MI-LIFETIME-MALE-YEARS / P-MI-LIFETIME-FEMALE-YEARS 提供；缺失时进入人工确认。",
  "inputs": [
    {
      "key": "user.basic.gender",
      "type": "string",
      "required": true
    },
    {
      "key": "user.social.medical_contrib_months",
      "type": "number",
      "required": true
    }
  ],
  "parameter_refs": [
    {
      "param_id": "P-MI-LIFETIME-MALE-YEARS",
      "purpose": "男性终身医保所需年限"
    },
    {
      "param_id": "P-MI-LIFETIME-FEMALE-YEARS",
      "purpose": "女性终身医保所需年限"
    }
  ],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_missing",
        "when": {
          "or": [
            {
              "==": [
                {
                  "var": "user.social.medical_contrib_months"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "user.basic.gender"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-MI-MONTHS",
                "text": "请提供医保累计缴费月数和性别（用于判断是否满足终身医保条件）。",
                "field": "user.social.medical_contrib_months"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_1b_local_years_missing",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.basic.gender"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "user.social.medical_contrib_months"
                },
                null
              ]
            },
            {
              "or": [
                {
                  "and": [
                    {
                      "==": [
                        {
                          "var": "user.basic.gender"
                        },
                        "male"
                      ]
                    },
                    {
                      "==": [
                        {
                          "var": "params.P-MI-LIFETIME-MALE-YEARS"
                        },
                        null
                      ]
                    }
                  ]
                },
                {
                  "and": [
                    {
                      "==": [
                        {
                          "var": "user.basic.gender"
                        },
                        "female"
                      ]
                    },
                    {
                      "==": [
                        {
                          "var": "params.P-MI-LIFETIME-FEMALE-YEARS"
                        },
                        null
                      ]
                    }
                  ]
                }
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-MI-LOCAL-YEARS-MISSING",
                "text": "参保地医保退休最低缴费年限参数未配置（国家框架由社会保险法第27条授权统筹地区规定），需人工确认后补充地区参数。"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_male",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.basic.gender"
                },
                "male"
              ]
            },
            {
              "!=": [
                {
                  "var": "user.social.medical_contrib_months"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.mi.lifetime_required_months",
              "value": {
                "*": [
                  {
                    "var": "params.P-MI-LIFETIME-MALE-YEARS"
                  },
                  12
                ]
              }
            },
            {
              "type": "set",
              "path": "calc.mi.lifetime_gap_months",
              "value": {
                "max": [
                  0,
                  {
                    "-": [
                      {
                        "var": "calc.mi.lifetime_required_months"
                      },
                      {
                        "var": "user.social.medical_contrib_months"
                      }
                    ]
                  }
                ]
              }
            }
          ]
        }
      },
      {
        "row_id": "row_3_female",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.basic.gender"
                },
                "female"
              ]
            },
            {
              "!=": [
                {
                  "var": "user.social.medical_contrib_months"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.mi.lifetime_required_months",
              "value": {
                "*": [
                  {
                    "var": "params.P-MI-LIFETIME-FEMALE-YEARS"
                  },
                  12
                ]
              }
            },
            {
              "type": "set",
              "path": "calc.mi.lifetime_gap_months",
              "value": {
                "max": [
                  0,
                  {
                    "-": [
                      {
                        "var": "calc.mi.lifetime_required_months"
                      },
                      {
                        "var": "user.social.medical_contrib_months"
                      }
                    ]
                  }
                ]
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.mi.lifetime_gap_months",
      "type": "number"
    },
    {
      "key": "calc.mi.lifetime_required_months",
      "type": "number"
    }
  ],
  "examples": [
    {
      "name": "男性已缴200月，需300月 -> 缺100月",
      "input": {
        "user": {
          "basic": {
            "gender": "male"
          },
          "social": {
            "medical_contrib_months": 200
          }
        },
        "params": {
          "P-MI-LIFETIME-MALE-YEARS": 25
        }
      },
      "expected": {
        "calc": {
          "mi": {
            "lifetime_gap_months": 100,
            "lifetime_required_months": 300
          }
        }
      }
    },
    {
      "name": "女性已缴200月，需240月 -> 缺40月",
      "input": {
        "user": {
          "basic": {
            "gender": "female"
          },
          "social": {
            "medical_contrib_months": 200
          }
        },
        "params": {
          "P-MI-LIFETIME-FEMALE-YEARS": 20
        }
      },
      "expected": {
        "calc": {
          "mi": {
            "lifetime_gap_months": 40,
            "lifetime_required_months": 240
          }
        }
      }
    },
    {
      "name": "女性已缴240月，需240月 -> 无缺口",
      "input": {
        "user": {
          "basic": {
            "gender": "female"
          },
          "social": {
            "medical_contrib_months": 240
          }
        },
        "params": {
          "P-MI-LIFETIME-FEMALE-YEARS": 20
        }
      },
      "expected": {
        "calc": {
          "mi": {
            "lifetime_gap_months": 0,
            "lifetime_required_months": 240
          }
        }
      }
    }
  ],
  "evidence": [
    {
      "document_id": "DOC-CN-SOCIAL-INSURANCE-LAW",
      "jurisdiction_code": "CN",
      "title": "中华人民共和国社会保险法（2018修正）",
      "authority": "全国人民代表大会常务委员会",
      "official_url": "https://www.mohrss.gov.cn/xxgk2020/fdzdgknr/zcfg/fl/202011/t20201102_394629.html",
      "fetched_at": "2026-09-05T13:38:56.250Z",
      "content_sha256": "b69d5d490f9b6b70394dfb670c2e1a0a959f306e70380bb678ee4866f947d464",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/CN/DOC-CN-SOCIAL-INSURANCE-LAW/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "article",
        "reference": "第二十七条"
      },
      "excerpt": "参加职工基本医疗保险的个人，达到法定退休年龄时累计缴费达到国家规定年限的，退休后不再缴纳基本医疗保险费，按照国家规定享受基本医疗保险待遇；未达到国家规定年限的，可以缴费至国家规定年限。"
    }
  ],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-300-MI-GAP:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-300-MI-GAP-MONTHS",
  "name": "计算医保断缴月数（上次结束 -> 本次参保）",
  "module": "medical_insurance",
  "status": "published",
  "priority": 300,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "date_diff_months 建议按“自然月差”计算（与经办口径一致），并在文档中定义清楚。",
  "inputs": [
    {
      "key": "user.mi.prev_end_date",
      "type": "date",
      "required": false,
      "desc": "上次医保结束日期（职工/居民）"
    },
    {
      "key": "user.mi.enroll_date",
      "type": "date",
      "required": true,
      "desc": "本次参保日期（例如灵活就业医保起始）"
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_missing_enroll",
        "when": {
          "==": [
            {
              "var": "user.mi.enroll_date"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-MI-ENROLL-DATE",
                "text": "请提供本次医保参保日期（用于计算等待期/衔接）。",
                "field": "user.mi.enroll_date"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_missing_prev_end",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.mi.enroll_date"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "user.mi.prev_end_date"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.mi.gap_months",
              "value": null
            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-MI-PREV-END-MISSING",
                "text": "缺少上次医保结束日期，将无法精确判断是否触发等待期；建议上传参保记录或补充信息。"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_3_compute",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.mi.enroll_date"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "user.mi.prev_end_date"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "call",
              "fn": "date_diff_months",
              "args": {
                "from": {
                  "var": "user.mi.prev_end_date"
                },
                "to": {
                  "var": "user.mi.enroll_date"
                }
              },
              "into": "calc.mi.gap_months"
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.mi.gap_months",
      "type": "number"
    },
    {
      "key": "calc.warnings",
      "type": "array"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    }
  ],
  "examples": [
    {
      "name": "断缴3个月",
      "input": {
        "user": {
          "mi": {
            "prev_end_date": "2025-12-31",
            "enroll_date": "2026-03-01"
          }
        }
      },
      "expected": {
        "calc": {
          "mi": {
            "gap_months": 3
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-400-UNEMPL:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-400-UNEMPLOYMENT-ELIGIBILITY",
  "name": "失业金领取资格初判（简化：失业状态+失业险年限）",
  "module": "unemployment",
  "status": "published",
  "priority": 400,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "仅做初判；真实资格还涉及非本人意愿中断就业、求职登记、年龄等条件，应在 Admin 中配置补充规则或标记需人工核对。",
  "inputs": [
    {
      "key": "user.status.employment_status",
      "type": "string",
      "required": true
    },
    {
      "key": "user.social.unemployment_insurance_years",
      "type": "number",
      "required": false
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_not_unemployed",
        "when": {
          "!=": [
            {
              "var": "user.status.employment_status"
            },
            "unemployed"
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.unemployment.eligible",
              "value": false
            }
          ]
        }
      },
      {
        "row_id": "row_2_missing_years",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.status.employment_status"
                },
                "unemployed"
              ]
            },
            {
              "==": [
                {
                  "var": "user.social.unemployment_insurance_years"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.unemployment.eligible",
              "value": null
            },
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-UI-YEARS",
                "text": "请提供失业保险累计缴费年限（用于核算可领失业金月数）。",
                "field": "user.social.unemployment_insurance_years"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_3_years_ge_1",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.status.employment_status"
                },
                "unemployed"
              ]
            },
            {
              ">=": [
                {
                  "var": "user.social.unemployment_insurance_years"
                },
                1
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.unemployment.eligible",
              "value": true
            }
          ]
        }
      },
      {
        "row_id": "row_4_years_lt_1",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.status.employment_status"
                },
                "unemployed"
              ]
            },
            {
              "<": [
                {
                  "var": "user.social.unemployment_insurance_years"
                },
                1
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.unemployment.eligible",
              "value": false
            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-UI-NOT-ELIGIBLE",
                "text": "失业险缴费年限不足1年，可能无法领取失业金（需以经办核定为准）。"
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.unemployment.eligible",
      "type": "boolean"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    },
    {
      "key": "calc.warnings",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "失业且失业险2年 -> eligible",
      "input": {
        "user": {
          "status": {
            "employment_status": "unemployed"
          },
          "social": {
            "unemployment_insurance_years": 2
          }
        }
      },
      "expected": {
        "calc": {
          "unemployment": {
            "eligible": true
          }
        }
      }
    }
  ],
  "evidence": [
    {
      "document_id": "DOC-CN-SOCIAL-INSURANCE-LAW",
      "jurisdiction_code": "CN",
      "title": "中华人民共和国社会保险法（2018修正）",
      "authority": "全国人民代表大会常务委员会",
      "official_url": "https://www.mohrss.gov.cn/xxgk2020/fdzdgknr/zcfg/fl/202011/t20201102_394629.html",
      "fetched_at": "2026-09-05T13:38:56.250Z",
      "content_sha256": "b69d5d490f9b6b70394dfb670c2e1a0a959f306e70380bb678ee4866f947d464",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/CN/DOC-CN-SOCIAL-INSURANCE-LAW/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "article",
        "reference": "第四十五条"
      },
      "excerpt": "失业人员符合下列条件的，从失业保险基金中领取失业保险金：（一）失业前用人单位和本人已经缴纳失业保险费满一年的；（二）非因本人意愿中断就业的；（三）已经进行失业登记，并有求职要求的。"
    },
    {
      "document_id": "DOC-CN-UNEMPLOYMENT-REGULATION",
      "jurisdiction_code": "CN",
      "title": "失业保险条例（国务院令第258号）",
      "authority": "国务院",
      "official_url": "https://www.mohrss.gov.cn/xxgk2020/fdzdgknr/zcfg/fg/202011/t20201103_394936.html",
      "fetched_at": "2026-09-05T13:43:01.660Z",
      "content_sha256": "b8187965656565984549569e9894a62cb3960f5a64aacac3749b80be2d7a3e04",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/CN/DOC-CN-UNEMPLOYMENT-REGULATION/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "article",
        "reference": "第十四条"
      },
      "excerpt": "具备下列条件的失业人员，可以领取失业保险金：（一）按照规定参加失业保险，所在单位和本人已按照规定履行缴费义务满1年的；（二）非因本人意愿中断就业的；（三）已办理失业登记，并有求职要求的。"
    }
  ],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-410-UNEMPL:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-410-UNEMPLOYMENT-DURATION",
  "name": "失业金可领取月数核算（按失业险年限查表 + 上限）",
  "module": "unemployment",
  "status": "published",
  "priority": 410,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "国家法定期限上限（社会保险法第四十六条、失业保险条例第十七条）：按累计缴费年限分档的最高领取月数。实际执行标准由参保地规定，地区可通过 replace 覆盖期限表 T-UNEMPLOYMENT-DURATION-BY-YEARS。",
  "inputs": [
    {
      "key": "calc.unemployment.eligible",
      "type": "boolean",
      "required": true
    },
    {
      "key": "user.social.unemployment_insurance_years",
      "type": "number",
      "required": false
    },
    {
      "key": "params.P-UNEMPLOYMENT-MAX-MONTHS",
      "type": "number",
      "required": true
    }
  ],
  "parameter_refs": [
    {
      "param_id": "T-UNEMPLOYMENT-DURATION-BY-YEARS",
      "purpose": "失业金领取月数表"
    },
    {
      "param_id": "P-UNEMPLOYMENT-MAX-MONTHS",
      "purpose": "失业金上限月数"
    }
  ],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_not_eligible",
        "when": {
          "==": [
            {
              "var": "calc.unemployment.eligible"
            },
            false
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.unemployment.duration_months",
              "value": 0
            }
          ]
        }
      },
      {
        "row_id": "row_2_unknown",
        "when": {
          "==": [
            {
              "var": "calc.unemployment.eligible"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.unemployment.duration_months",
              "value": null
            }
          ]
        }
      },
      {
        "row_id": "row_3_missing_years",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.unemployment.eligible"
                },
                true
              ]
            },
            {
              "==": [
                {
                  "var": "user.social.unemployment_insurance_years"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.unemployment.duration_months",
              "value": null
            },
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-UI-YEARS",
                "text": "缺少失业险缴费年限，无法核算可领失业金月数。",
                "field": "user.social.unemployment_insurance_years"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_4_lookup",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.unemployment.eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "user.social.unemployment_insurance_years"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "lookup",
              "table_param_id": "T-UNEMPLOYMENT-DURATION-BY-YEARS",
              "key": {
                "insured_years": {
                  "var": "user.social.unemployment_insurance_years"
                }
              },
              "into": "calc.unemployment.duration_months_raw"
            },
            {
              "type": "set",
              "path": "calc.unemployment.duration_months",
              "value": {
                "min": [
                  {
                    "var": "calc.unemployment.duration_months_raw"
                  },
                  {
                    "var": "params.P-UNEMPLOYMENT-MAX-MONTHS"
                  }
                ]
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.unemployment.duration_months",
      "type": "number"
    },
    {
      "key": "calc.unemployment.duration_months_raw",
      "type": "number"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "失业险8年 -> 24月(上限)",
      "input": {
        "calc": {
          "unemployment": {
            "eligible": true
          }
        },
        "user": {
          "social": {
            "unemployment_insurance_years": 8
          }
        },
        "params": {
          "P-UNEMPLOYMENT-MAX-MONTHS": 24,
          "T-UNEMPLOYMENT-DURATION-BY-YEARS": [
            {
              "insured_years_min": 8,
              "insured_years_max": 99,
              "months": 24
            }
          ]
        }
      },
      "expected": {
        "calc": {
          "unemployment": {
            "duration_months": 24
          }
        }
      }
    }
  ],
  "evidence": [
    {
      "document_id": "DOC-CN-SOCIAL-INSURANCE-LAW",
      "jurisdiction_code": "CN",
      "title": "中华人民共和国社会保险法（2018修正）",
      "authority": "全国人民代表大会常务委员会",
      "official_url": "https://www.mohrss.gov.cn/xxgk2020/fdzdgknr/zcfg/fl/202011/t20201102_394629.html",
      "fetched_at": "2026-09-05T13:38:56.250Z",
      "content_sha256": "b69d5d490f9b6b70394dfb670c2e1a0a959f306e70380bb678ee4866f947d464",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/CN/DOC-CN-SOCIAL-INSURANCE-LAW/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "article",
        "reference": "第四十六条"
      },
      "excerpt": "失业人员失业前用人单位和本人累计缴费满一年不足五年的，领取失业保险金的期限最长为十二个月；累计缴费满五年不足十年的，领取失业保险金的期限最长为十八个月；累计缴费十年以上的，领取失业保险金的期限最长为二十四个月。"
    },
    {
      "document_id": "DOC-CN-UNEMPLOYMENT-REGULATION",
      "jurisdiction_code": "CN",
      "title": "失业保险条例（国务院令第258号）",
      "authority": "国务院",
      "official_url": "https://www.mohrss.gov.cn/xxgk2020/fdzdgknr/zcfg/fg/202011/t20201103_394936.html",
      "fetched_at": "2026-09-05T13:43:01.660Z",
      "content_sha256": "b8187965656565984549569e9894a62cb3960f5a64aacac3749b80be2d7a3e04",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/CN/DOC-CN-UNEMPLOYMENT-REGULATION/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "article",
        "reference": "第十七条"
      },
      "excerpt": "失业人员失业前所在单位和本人按照规定累计缴费时间满1年不足5年的，领取失业保险金的期限最长为12个月；累计缴费时间满5年不足10年的，领取失业保险金的期限最长为18个月；累计缴费时间10年以上的，领取失业保险金的期限最长为24个月。"
    }
  ],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-420-UI-MED:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-420-UI-MEDICAL-COVERAGE",
  "name": "失业金期间医保由基金代缴提示（规划成本口径）",
  "module": "unemployment",
  "status": "published",
  "priority": 420,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "",
  "inputs": [
    {
      "key": "user.status.on_unemployment_benefit",
      "type": "boolean",
      "required": false
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_on_benefit",
        "when": {
          "==": [
            {
              "var": "user.status.on_unemployment_benefit"
            },
            true
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.mi.paid_by_unemployment_fund",
              "value": true
            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-UI-MI-PAID",
                "text": "失业金期间，医保通常由失业保险基金代缴（以经办口径为准）。规划现金流时请不要重复计算医保个人缴费。"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_not_on_benefit_or_unknown",
        "when": {
          "or": [
            {
              "==": [
                {
                  "var": "user.status.on_unemployment_benefit"
                },
                false
              ]
            },
            {
              "==": [
                {
                  "var": "user.status.on_unemployment_benefit"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.mi.paid_by_unemployment_fund",
              "value": false
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.mi.paid_by_unemployment_fund",
      "type": "boolean"
    },
    {
      "key": "calc.warnings",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "正在领取失业金 -> 医保基金代缴提示",
      "input": {
        "user": {
          "status": {
            "on_unemployment_benefit": true
          }
        }
      },
      "expected": {
        "calc": {
          "mi": {
            "paid_by_unemployment_fund": true
          }
        }
      }
    }
  ],
  "evidence": [
    {
      "document_id": "DOC-CN-SOCIAL-INSURANCE-LAW",
      "jurisdiction_code": "CN",
      "title": "中华人民共和国社会保险法（2018修正）",
      "authority": "全国人民代表大会常务委员会",
      "official_url": "https://www.mohrss.gov.cn/xxgk2020/fdzdgknr/zcfg/fl/202011/t20201102_394629.html",
      "fetched_at": "2026-09-05T13:38:56.250Z",
      "content_sha256": "b69d5d490f9b6b70394dfb670c2e1a0a959f306e70380bb678ee4866f947d464",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/CN/DOC-CN-SOCIAL-INSURANCE-LAW/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "article",
        "reference": "第四十八条"
      },
      "excerpt": "失业人员在领取失业保险金期间，参加职工基本医疗保险，享受基本医疗保险待遇。失业人员应当缴纳的基本医疗保险费从失业保险基金中支付，个人不缴纳基本医疗保险费。"
    }
  ],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-700-PLAN-T:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-700-PLAN-TEMPLATE",
  "name": "规划方案模板选择（规则引擎可直接输出的主骨架）",
  "module": "plan",
  "status": "published",
  "priority": 700,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "模板仅决定“方案骨架”。具体 Timeline 由模板渲染器/Agent 根据 calc 结果填充细节。",
  "inputs": [
    {
      "key": "calc.needs_agent",
      "type": "boolean",
      "required": false
    },
    {
      "key": "user.status.employment_status",
      "type": "string",
      "required": false
    },
    {
      "key": "calc.unemployment.eligible",
      "type": "boolean",
      "required": false
    },
    {
      "key": "calc.subsidy.selected_option",
      "type": "string",
      "required": false
    },
    {
      "key": "calc.mi.waiting_required",
      "type": "boolean",
      "required": false
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_needs_agent",
        "when": {
          "==": [
            {
              "var": "calc.needs_agent"
            },
            true
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "plan.conclusion_level",
              "value": "needs_agent"
            },
            {
              "type": "set",
              "path": "plan.template_id",
              "value": "T-AGENT-ASSIST"
            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-NEEDS-AGENT",
                "text": "关键信息不完整或存在互斥冲突，建议进入 Agent 追问/细化模式后再生成完整方案。"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_unemployed_path",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "calc.needs_agent"
                },
                true
              ]
            },
            {
              "==": [
                {
                  "var": "user.status.employment_status"
                },
                "unemployed"
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "plan.conclusion_level",
              "value": "direct"
            },
            {
              "type": "set",
              "path": "plan.template_id",
              "value": "T-UNEMPLOYMENT-PLANNING"
            },
            {
              "type": "set",
              "path": "plan.primary_strategy",
              "value": "失业路径：优先用失业金期覆盖社保/医保衔接，再衔接补贴或灵活就业"
            }
          ]
        }
      },
      {
        "row_id": "row_3_flexible_path",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "calc.needs_agent"
                },
                true
              ]
            },
            {
              "==": [
                {
                  "var": "user.status.employment_status"
                },
                "flexible"
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "plan.conclusion_level",
              "value": "direct"
            },
            {
              "type": "set",
              "path": "plan.template_id",
              "value": "T-FLEXIBLE-PLANNING"
            },
            {
              "type": "set",
              "path": "plan.primary_strategy",
              "value": "灵活就业路径：按目标选择基数与补贴，重点控制医保等待期与补贴互斥"
            }
          ]
        }
      },
      {
        "row_id": "row_4_employed_path",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "calc.needs_agent"
                },
                true
              ]
            },
            {
              "==": [
                {
                  "var": "user.status.employment_status"
                },
                "employed"
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "plan.conclusion_level",
              "value": "direct"
            },
            {
              "type": "set",
              "path": "plan.template_id",
              "value": "T-EMPLOYED-PLANNING"
            },
            {
              "type": "set",
              "path": "plan.primary_strategy",
              "value": "在职路径：保持连续缴费，关注基数变动/补差，评估未来失业金与补贴窗口"
            }
          ]
        }
      },
      {
        "row_id": "row_5_default",
        "when": {},
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "plan.conclusion_level",
              "value": "needs_agent"
            },
            {
              "type": "set",
              "path": "plan.template_id",
              "value": "T-AGENT-ASSIST"
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-STATUS",
                "text": "请确认当前状态：在职/失业/灵活就业/退休。不同状态规划路径完全不同。",
                "field": "user.status.employment_status"
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "plan.template_id",
      "type": "string"
    },
    {
      "key": "plan.conclusion_level",
      "type": "string"
    },
    {
      "key": "plan.primary_strategy",
      "type": "string"
    },
    {
      "key": "calc.warnings",
      "type": "array"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "信息齐全且失业 -> 失业模板",
      "input": {
        "calc": {
          "needs_agent": false
        },
        "user": {
          "status": {
            "employment_status": "unemployed"
          }
        }
      },
      "expected": {
        "plan": {
          "template_id": "T-UNEMPLOYMENT-PLANNING",
          "conclusion_level": "direct"
        }
      }
    }
  ],
  "evidence": [],
  "operation": "baseline"
}

files.dsl/regions/cn_dsl_v1/rules/R-900-FINAL-:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-900-FINAL-GATE",
  "name": "最终Gate：关键字段缺失/冲突 -> needs_agent",
  "module": "gate",
  "status": "published",
  "priority": 900,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "该 Gate 主要保证系统不会在关键字段缺失时输出“伪结论”。",
  "inputs": [
    {
      "key": "user.basic.gender",
      "type": "string",
      "required": true
    },
    {
      "key": "user.basic.birth_year",
      "type": "number",
      "required": true
    },
    {
      "key": "user.status.employment_status",
      "type": "string",
      "required": true
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_any_missing",
        "when": {
          "or": [
            {
              "==": [
                {
                  "var": "user.basic.gender"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "user.basic.birth_year"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "user.status.employment_status"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-CORE",
                "text": "缺少核心信息（性别/出生年份/当前状态），无法生成可执行规划。请补齐。"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_ok",
        "when": {},
        "then": {
          "actions": []
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "缺出生年份 -> needs_agent",
      "input": {
        "user": {
          "basic": {
            "gender": "male",
            "birth_year": null
          },
          "status": {
            "employment_status": "employed"
          }
        }
      },
      "expected": {
        "calc": {
          "needs_agent": true
        }
      }
    }
  ],
  "evidence": [],
  "operation": "baseline"
}

files.dsl/regions/guangdong_dsl_v1/rules/R-GD-:
{
  "rule_id": "R-GD-UI-AMOUNT",
  "name": "广东失业保险金月标准（按失业保险金领取地市最低工资×90%）",
  "module": "unemployment",
  "dsl_version": "SOCILA-DSL-1.0",
  "priority": 430,
  "effective_from": "2025-01-12",
  "effective_to": null,
  "supersedes": [],
  "operation": "add",
  "target_business_key": null,
  "status": "published",
  "inputs": [
    {
      "key": "calc.unemployment.eligible",
      "type": "boolean",
      "required": true,
      "desc": "失业资格结论（R-400输出）；false/未知时不估算金额"
    },
    {
      "key": "user.profile.claim_city",
      "type": "string",
      "required": false,
      "desc": "失业保险金领取地市（广东省条例第十九条：按领取地地级以上市最低工资标准计发；由用户确认后传递，系统不猜测）"
    },
    {
      "key": "params.T-GD-MIN-WAGE-BY-CITY",
      "type": "table",
      "required": true,
      "desc": "广东省最低工资分市表（粤府函〔2026〕188号，2026-09-01起）"
    },
    {
      "key": "params.P-GD-UNEMPLOYMENT-BENEFIT-RATE",
      "type": "number",
      "required": true,
      "desc": "失业保险金计发比例90%（广东省失业保险条例第十九条）"
    }
  ],
  "parameter_refs": [
    {
      "param_id": "T-GD-MIN-WAGE-BY-CITY",
      "purpose": "失业保险金领取地市最低工资（分市表，2026-09-01起）"
    },
    {
      "param_id": "P-GD-UNEMPLOYMENT-BENEFIT-RATE",
      "purpose": "失业保险金计发比例90%（条例第十九条）"
    }
  ],
  "outputs": [
    {
      "key": "calc.unemployment.monthly_amount_est",
      "type": "number"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.warnings",
      "type": "array"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "decision_table": {
    "hit_policy": "all",
    "rows": [
      {
        "row_id": "row_1_not_eligible",
        "when": {
          "==": [
            {
              "var": "calc.unemployment.eligible"
            },
            false
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.unemployment.monthly_amount_est",
              "value": 0
            }
          ]
        }
      },
      {
        "row_id": "row_2_unknown",
        "when": {
          "==": [
            {
              "var": "calc.unemployment.eligible"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.unemployment.monthly_amount_est",
              "value": null
            }
          ]
        }
      },
      {
        "row_id": "row_3_missing_city",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.unemployment.eligible"
                },
                true
              ]
            },
            {
              "==": [
                {
                  "var": "user.profile.claim_city"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-UI-CLAIM-CITY",
                "text": "请确认失业保险金领取地市（用于按领取地市最低工资标准核算失业金金额）。",
                "field": "user.profile.claim_city"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_4_lookup_wage",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.unemployment.eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "user.profile.claim_city"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "lookup",
              "table_param_id": "T-GD-MIN-WAGE-BY-CITY",
              "key": {
                "city": {
                  "var": "user.profile.claim_city"
                }
              },
              "into": "calc.unemployment._min_wage_row",
              "into_map": {
                "monthly": "calc.unemployment._min_wage_monthly",
                "tier": "calc.unemployment._min_wage_tier"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_5_wage_missing",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.unemployment.eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "user.profile.claim_city"
                },
                null
              ]
            },
            {
              "==": [
                {
                  "var": "calc.unemployment._min_wage_monthly"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-UI-MIN-WAGE-MISSING",
                "text": "领取地市不在当前最低工资表中或最低工资缺失，无法核算失业保险金金额，需人工确认领取地市。"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_6_compute",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.unemployment.eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "user.profile.claim_city"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.unemployment._min_wage_monthly"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.unemployment.monthly_amount_est",
              "value": {
                "*": [
                  {
                    "var": "calc.unemployment._min_wage_monthly"
                  },
                  {
                    "var": "params.P-GD-UNEMPLOYMENT-BENEFIT-RATE"
                  }
                ]
              }
            }
          ]
        }
      }
    ]
  },
  "examples": [
    {
      "input": {
        "user": {
          "profile": {
            "claim_city": "广州"
          },
          "status": {
            "employment_status": "unemployed"
          },
          "social": {
            "unemployment_insurance_years": 3
          }
        },
        "calc": {
          "unemployment": {
            "eligible": true
          }
        }
      },
      "expected": {
        "calc": {
          "unemployment": {
            "monthly_amount_est": 2412
          }
        }
      },
      "name": "广州领取：2680元/月最低工资×90%＝2412元/月"
    },
    {
      "input": {
        "user": {
          "status": {
            "employment_status": "unemployed"
          }
        },
        "calc": {
          "unemployment": {
            "eligible": true
          }
        }
      },
      "expected": {
        "calc": {
          "needs_agent": true
        }
      },
      "name": "领取地市缺失：不猜测金额，转入人工确认"
    },
    {
      "input": {
        "user": {
          "profile": {
            "claim_city": "未收录市"
          },
          "status": {
            "employment_status": "unemployed"
          }
        },
        "calc": {
          "unemployment": {
            "eligible": true
          }
        }
      },
      "expected": {
        "calc": {
          "needs_agent": true,
          "warnings": [
            {
              "warning_id": "W-UI-MIN-WAGE-MISSING"
            }
          ]
        }
      },
      "name": "领取地市不在最低工资表：needs_agent且金额为空"
    },
    {
      "input": {
        "user": {
          "profile": {
            "claim_city": "广州"
          },
          "status": {
            "employment_status": "employed"
          }
        },
        "calc": {
          "unemployment": {
            "eligible": false
          }
        }
      },
      "expected": {
        "calc": {
          "unemployment": {
            "monthly_amount_est": 0
          }
        }
      },
      "name": "失业资格不满足：金额为0"
    }
  ],
  "evidence": [
    {
      "document_id": "DOC-GD-UNEMPLOYMENT-REGULATION",
      "jurisdiction_code": "440000",
      "title": "广东省失业保险条例（2002年通过、2013年修订、2022年第一次修正、2025年1月12日第二次修正）",
      "authority": "广东省人民代表大会常务委员会",
      "official_url": "https://hrss.gd.gov.cn/gkmlpt/content/4/4669/post_4669825.html",
      "fetched_at": "2026-09-06T14:07:25.406Z",
      "content_sha256": "15f3551f796ae24058b996c75d5220a79115dc9a82915cbff537b008d28e4456",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/GD/DOC-GD-UNEMPLOYMENT-REGULATION/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "body",
        "reference": "第十九条"
      },
      "excerpt": "第十九条 失业保险金由社会保险经办机构按照失业保险金领取地地级以上市最低工资标准的百分之九十按月计发，省人民政府根据国家规定可以适当调整失业保险金标准。"
    },
    {
      "document_id": "DOC-GD-MINIMUM-WAGE-2026",
      "jurisdiction_code": "440000",
      "title": "广东省人民政府关于调整我省最低工资标准的通知（粤府函〔2026〕188号）",
      "authority": "广东省人民政府",
      "official_url": "https://www.gd.gov.cn/zwgk/wjk/qbwj/yfh/content/post_4942177.html",
      "fetched_at": "2026-09-07T02:13:46.755Z",
      "content_sha256": "de716e1c054d4fb232a9579985d0a83a40d240a3f35b859a933cf14cb2bc7513",
      "artifact": "docs/refactor/policy-ops-agent/reports/stage-09-05-national-baseline-overlays/evidence/GD/DOC-GD-MINIMUM-WAGE-2026/original.html",
      "parse_version": "extracted-text-v1",
      "locator": {
        "type": "body",
        "reference": "正文第一条及附件《广东省最低工资标准表》"
      },
      "excerpt": "从2026年9月1日起，对我省全日制就业劳动者月最低工资标准和非全日制小时最低工资标准进行调整，具体标准附后。"
    }
  ],
  "notes": "广东省失业保险条例第十九条：失业保险金按领取地地级以上市最低工资标准的90%按月计发。领取地市或最低工资缺失时输出needs_agent且不估算金额（任务2首期实现；领取地市由任务3确认后传递，本规则不猜测）。"
}

files.dsl/regions/shanghai_dsl_v1/rules/R-310-:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-310-MI-WAITING-PERIOD",
  "name": "医保等待期判定（断缴>阈值 -> 等待期）",
  "module": "medical_insurance",
  "status": "published",
  "priority": 310,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "",
  "inputs": [
    {
      "key": "calc.mi.gap_months",
      "type": "number",
      "required": false
    },
    {
      "key": "params.P-SH-MI-GAP-WAIVER-MONTHS",
      "type": "number",
      "required": true
    },
    {
      "key": "params.P-SH-MI-WAITING-PERIOD-MONTHS",
      "type": "number",
      "required": true
    }
  ],
  "parameter_refs": [
    {
      "param_id": "P-SH-MI-GAP-WAIVER-MONTHS",
      "purpose": "医保衔接免等待期阈值（月）"
    },
    {
      "param_id": "P-SH-MI-WAITING-PERIOD-MONTHS",
      "purpose": "灵活就业医保等待期（月）"
    }
  ],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_gap_unknown",
        "when": {
          "==": [
            {
              "var": "calc.mi.gap_months"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.mi.waiting_period_months",
              "value": null
            },
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-MI-GAP",
                "text": "无法判断医保断缴月数，可能影响等待期。请补充上次医保结束日期。",
                "field": "user.mi.prev_end_date"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_no_waiting",
        "when": {
          "<=": [
            {
              "var": "calc.mi.gap_months"
            },
            {
              "var": "params.P-SH-MI-GAP-WAIVER-MONTHS"
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.mi.waiting_period_months",
              "value": 0
            },
            {
              "type": "set",
              "path": "calc.mi.waiting_required",
              "value": false
            }
          ]
        }
      },
      {
        "row_id": "row_3_need_waiting",
        "when": {
          ">": [
            {
              "var": "calc.mi.gap_months"
            },
            {
              "var": "params.P-SH-MI-GAP-WAIVER-MONTHS"
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.mi.waiting_period_months",
              "value": {
                "var": "params.P-SH-MI-WAITING-PERIOD-MONTHS"
              }
            },
            {
              "type": "set",
              "path": "calc.mi.waiting_required",
              "value": true
            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-MI-WAITING",
                "text": "医保断缴超过阈值，可能触发等待期；规划中需优先保证医保连续性。"
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.mi.waiting_period_months",
      "type": "number"
    },
    {
      "key": "calc.mi.waiting_required",
      "type": "boolean"
    },
    {
      "key": "calc.warnings",
      "type": "array"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "断缴2个月 <=3 -> 0等待期",
      "input": {
        "calc": {
          "mi": {
            "gap_months": 2
          }
        },
        "params": {
          "P-SH-MI-GAP-WAIVER-MONTHS": 3,
          "P-SH-MI-WAITING-PERIOD-MONTHS": 6
        }
      },
      "expected": {
        "calc": {
          "mi": {
            "waiting_period_months": 0,
            "waiting_required": false
          }
        }
      }
    },
    {
      "name": "断缴5个月 -> 6个月等待期",
      "input": {
