          "subsidy": {
            "4050_eligible": true
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "add"
}

files.dsl/regions/shanghai_dsl_v1/rules/R-510-:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-510-4050-AMOUNT",
  "name": "4050补贴金额估算（基数下限 * 缴费比例 * 补贴比例）",
  "module": "subsidy",
  "status": "published",
  "priority": 510,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "此为估算。实际4050补贴通常按“基数下限对应缴费额的50%”口径发放，且仅覆盖指定险种；以经办为准。",
  "inputs": [
    {
      "key": "calc.subsidy.4050_eligible",
      "type": "boolean",
      "required": true
    },
    {
      "key": "user.social.base_lower_amount_per_month",
      "type": "number",
      "required": false,
      "desc": "缴费基数下限（月）"
    },
    {
      "key": "params.P-SH-PENSION-RATE-FLEX",
      "type": "number",
      "required": true
    },
    {
      "key": "params.P-SH-MEDICAL-RATE-FLEX",
      "type": "number",
      "required": true
    },
    {
      "key": "params.P-SH-4050-SUBSIDY-RATE",
      "type": "number",
      "required": true
    }
  ],
  "parameter_refs": [
    {
      "param_id": "P-SH-PENSION-RATE-FLEX"
    },
    {
      "param_id": "P-SH-MEDICAL-RATE-FLEX"
    },
    {
      "param_id": "P-SH-4050-SUBSIDY-RATE"
    }
  ],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_not_eligible",
        "when": {
          "or": [
            {
              "==": [
                {
                  "var": "calc.subsidy.4050_eligible"
                },
                false
              ]
            },
            {
              "==": [
                {
                  "var": "calc.subsidy.4050_eligible"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.4050_amount_est",
              "value": 0
            }
          ]
        }
      },
      {
        "row_id": "row_2_missing_base",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.subsidy.4050_eligible"
                },
                true
              ]
            },
            {
              "==": [
                {
                  "var": "user.social.base_lower_amount_per_month"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.4050_amount_est",
              "value": null
            },
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-BASE-LOWER",
                "text": "请提供当前缴费基数下限（或选择“按下限缴费”），用于估算4050补贴金额。",
                "field": "user.social.base_lower_amount_per_month"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_3_compute",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.subsidy.4050_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "user.social.base_lower_amount_per_month"
                },
                null
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.flex_cost_est",
              "value": {
                "*": [
                  {
                    "var": "user.social.base_lower_amount_per_month"
                  },
                  {
                    "+": [
                      {
                        "var": "params.P-SH-PENSION-RATE-FLEX"
                      },
                      {
                        "var": "params.P-SH-MEDICAL-RATE-FLEX"
                      }
                    ]
                  }
                ]
              }
            },
            {
              "type": "set",
              "path": "calc.subsidy.4050_amount_est",
              "value": {
                "*": [
                  {
                    "var": "calc.subsidy.flex_cost_est"
                  },
                  {
                    "var": "params.P-SH-4050-SUBSIDY-RATE"
                  }
                ]
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.subsidy.4050_amount_est",
      "type": "number"
    },
    {
      "key": "calc.subsidy.flex_cost_est",
      "type": "number"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "下限基数5000，比例0.3，补贴50% -> 750",
      "input": {
        "calc": {
          "subsidy": {
            "4050_eligible": true
          }
        },
        "user": {
          "social": {
            "base_lower_amount_per_month": 5000
          }
        },
        "params": {
          "P-SH-PENSION-RATE-FLEX": 0.2,
          "P-SH-MEDICAL-RATE-FLEX": 0.1,
          "P-SH-4050-SUBSIDY-RATE": 0.5
        }
      },
      "expected": {
        "calc": {
          "subsidy": {
            "flex_cost_est": 1500,
            "4050_amount_est": 750
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "add"
}

files.dsl/regions/shanghai_dsl_v1/rules/R-520-:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-520-JOB-SUBSIDY-ELIGIBILITY",
  "name": "大龄岗位补贴（俗称4757）资格初判（距退休≤36个月）",
  "module": "subsidy",
  "status": "published",
  "priority": 520,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "岗位补贴通常按最低工资的一定比例发放，并要求就业/签合同/社保缴纳等条件；本规则只做窗口期初判。",
  "inputs": [
    {
      "key": "user.subsidy.months_to_legal_retire",
      "type": "number",
      "required": false,
      "desc": "距法定退休月数（可由引擎算出或用户填）"
    },
    {
      "key": "user.subsidy.has_employment_difficulty_cert",
      "type": "boolean",
      "required": false
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_missing_months",
        "when": {
          "==": [
            {
              "var": "user.subsidy.months_to_legal_retire"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.job_eligible",
              "value": null
            },
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-MONTHS-TO-RETIRE",
                "text": "缺少“距退休月数”，无法判断是否进入大龄岗位补贴窗口（≤36个月）。",
                "field": "user.subsidy.months_to_legal_retire"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_2_not_difficulty",
        "when": {
          "==": [
            {
              "var": "user.subsidy.has_employment_difficulty_cert"
            },
            false
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.job_eligible",
              "value": false
            }
          ]
        }
      },
      {
        "row_id": "row_3_eligible",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.subsidy.months_to_legal_retire"
                },
                null
              ]
            },
            {
              "<=": [
                {
                  "var": "user.subsidy.months_to_legal_retire"
                },
                36
              ]
            },
            {
              "==": [
                {
                  "var": "user.subsidy.has_employment_difficulty_cert"
                },
                true
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.job_eligible",
              "value": true
            }
          ]
        }
      },
      {
        "row_id": "row_4_not_eligible",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.subsidy.months_to_legal_retire"
                },
                null
              ]
            },
            {
              ">": [
                {
                  "var": "user.subsidy.months_to_legal_retire"
                },
                36
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.job_eligible",
              "value": false
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.subsidy.job_eligible",
      "type": "boolean"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    }
  ],
  "examples": [
    {
      "name": "距退休30个月且就业困难 -> eligible",
      "input": {
        "user": {
          "subsidy": {
            "months_to_legal_retire": 30,
            "has_employment_difficulty_cert": true
          }
        }
      },
      "expected": {
        "calc": {
          "subsidy": {
            "job_eligible": true
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "add"
}

