            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-OLDER-UI-PENSION",
                "text": "如符合大龄条件，失业金期间养老最低档可能由失业基金承担；通常需要先缴后退并在退休前后办理，需按经办要求操作。"
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.subsidy.older_ui_pension_fund_eligible",
      "type": "boolean"
    },
    {
      "key": "calc.warnings",
      "type": "array"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    }
  ],
  "examples": [
    {
      "name": "领失业金且距退休10个月 -> eligible",
      "input": {
        "user": {
          "status": {
            "on_unemployment_benefit": true
          },
          "subsidy": {
            "months_to_legal_retire": 10
          }
        }
      },
      "expected": {
        "calc": {
          "subsidy": {
            "older_ui_pension_fund_eligible": true
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "add"
}

files.dsl/regions/shanghai_dsl_v1/rules/R-540-:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-540-SUBSIDY-MUTUAL-EXCLUSION",
  "name": "补贴/基金承担互斥与选择（4050 vs 岗位补贴 vs 大龄领金养老费承担）",
  "module": "subsidy",
  "status": "published",
  "priority": 540,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "互斥规则必须由 Admin 可配置：互斥矩阵、比较维度（净成本/养老金影响/医保连续性）、以及经办口径备注。",
  "inputs": [
    {
      "key": "calc.subsidy.4050_eligible",
      "type": "boolean",
      "required": false
    },
    {
      "key": "calc.subsidy.job_eligible",
      "type": "boolean",
      "required": false
    },
    {
      "key": "calc.subsidy.older_ui_pension_fund_eligible",
      "type": "boolean",
      "required": false
    },
    {
      "key": "calc.subsidy.4050_amount_est",
      "type": "number",
      "required": false
    },
    {
      "key": "calc.subsidy.job_amount_est",
      "type": "number",
      "required": false
    },
    {
      "key": "user.objective",
      "type": "string",
      "required": false
    }
  ],
  "parameter_refs": [],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_only_4050",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.subsidy.4050_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.job_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.older_ui_pension_fund_eligible"
                },
                true
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.selected_option",
              "value": "4050"
            }
          ]
        }
      },
      {
        "row_id": "row_2_only_job",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.subsidy.job_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.4050_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.older_ui_pension_fund_eligible"
                },
                true
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.selected_option",
              "value": "job_subsidy"
            }
          ]
        }
      },
      {
        "row_id": "row_3_only_older_ui",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "calc.subsidy.older_ui_pension_fund_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.4050_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.job_eligible"
                },
                true
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.selected_option",
              "value": "older_ui_pension_fund"
            }
          ]
        }
      },
      {
        "row_id": "row_4_none",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "calc.subsidy.4050_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.job_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.older_ui_pension_fund_eligible"
                },
                true
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.selected_option",
              "value": "none"
            }
          ]
        }
      },
      {
        "row_id": "row_5_conflict_min_cost_choose_job",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.objective"
                },
                "min_cost"
              ]
            },
            {
              "==": [
                {
                  "var": "calc.subsidy.4050_eligible"
                },
                true
              ]
            },
            {
              "==": [
                {
                  "var": "calc.subsidy.job_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.4050_amount_est"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.job_amount_est"
                },
                null
              ]
            },
            {
              ">": [
                {
                  "var": "calc.subsidy.job_amount_est"
                },
                {
                  "var": "calc.subsidy.4050_amount_est"
                }
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.selected_option",
              "value": "job_subsidy"
            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-SUBSIDY-CHOICE",
                "text": "同时符合4050与岗位补贴窗口，按“最低净成本”目标选择补贴金额更高的岗位补贴（估算）。请以经办互斥口径确认。"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_6_conflict_min_cost_choose_4050",
        "when": {
          "and": [
            {
              "==": [
                {
                  "var": "user.objective"
                },
                "min_cost"
              ]
            },
            {
              "==": [
                {
                  "var": "calc.subsidy.4050_eligible"
                },
                true
              ]
            },
            {
              "==": [
                {
                  "var": "calc.subsidy.job_eligible"
                },
                true
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.4050_amount_est"
                },
                null
              ]
            },
            {
              "!=": [
                {
                  "var": "calc.subsidy.job_amount_est"
                },
                null
              ]
            },
            {
              "<=": [
                {
                  "var": "calc.subsidy.job_amount_est"
                },
                {
                  "var": "calc.subsidy.4050_amount_est"
                }
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.selected_option",
              "value": "4050"
            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-SUBSIDY-CHOICE",
                "text": "同时符合4050与岗位补贴窗口，按“最低净成本”目标选择补贴金额更高/相当的4050（估算）。请以经办互斥口径确认。"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_7_conflict_need_agent",
        "when": {
          "or": [
            {
              "and": [
                {
                  "==": [
                    {
                      "var": "calc.subsidy.4050_eligible"
                    },
                    true
                  ]
                },
                {
                  "==": [
                    {
                      "var": "calc.subsidy.job_eligible"
                    },
                    true
                  ]
                }
              ]
            },
            {
              "and": [
                {
                  "==": [
                    {
                      "var": "calc.subsidy.4050_eligible"
                    },
                    true
                  ]
                },
                {
                  "==": [
                    {
                      "var": "calc.subsidy.older_ui_pension_fund_eligible"
                    },
                    true
                  ]
                }
              ]
            },
            {
              "and": [
                {
                  "==": [
                    {
                      "var": "calc.subsidy.job_eligible"
                    },
                    true
                  ]
                },
                {
                  "==": [
                    {
                      "var": "calc.subsidy.older_ui_pension_fund_eligible"
                    },
                    true
                  ]
                }
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.subsidy.selected_option",
              "value": "conflict"
            },
            {
              "type": "set",
              "path": "calc.needs_agent",
              "value": true
            },
            {
              "type": "emit_question",
              "value": {
                "question_id": "Q-SUBSIDY-CONFLICT",
                "text": "你可能同时落入多个补贴/基金承担窗口（例如4050与岗位补贴互斥）。请确认你的目标（省钱/多缴/医保连续性）并补充：基数下限、最低工资、是否已领失业金等，以便对比方案。",
                "field": "user.objective"
              }
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.subsidy.selected_option",
      "type": "string"
    },
    {
      "key": "calc.needs_agent",
      "type": "boolean"
    },
    {
      "key": "calc.agent_questions",
      "type": "array"
    },
    {
      "key": "calc.warnings",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "min_cost 且 job金额>4050 -> 选job",
      "input": {
        "user": {
          "objective": "min_cost"
        },
        "calc": {
          "subsidy": {
            "4050_eligible": true,
            "job_eligible": true,
            "4050_amount_est": 700,
            "job_amount_est": 1200
          }
        }
      },
      "expected": {
        "calc": {
          "subsidy": {
            "selected_option": "job_subsidy"
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "add"
}

files.dsl/regions/shanghai_dsl_v1/rules/R-600-:
{
  "dsl_version": "SOCILA-DSL-1.0",
  "rule_id": "R-600-PAY-GAP-REMINDER",
  "name": "社保补差提醒（社平/基数发布滞后导致7-8月差额）",
  "module": "contribution",
  "status": "published",
  "priority": 600,
  "effective_from": "2024-01-01",
  "effective_to": null,
  "supersedes": [],
  "notes": "when 中使用自定义 JSONLogic 操作符 intersects(a,b)：判断两个数组是否有交集。该规则用于输出“补差提醒”，具体补多少/如何补由经办页面展示为准。",
  "inputs": [
    {
      "key": "user.social.paid_months_in_year",
      "type": "array",
      "required": false,
      "desc": "当年已缴费月份列表（1-12）"
    }
  ],
  "parameter_refs": [
    {
      "param_id": "T-SH-PAY-GAP-MONTHS",
      "purpose": "可能触发补差的月份列表"
    }
  ],
  "decision_table": {
    "hit_policy": "first",
    "rows": [
      {
        "row_id": "row_1_no_data",
        "when": {
          "==": [
            {
              "var": "user.social.paid_months_in_year"
            },
            null
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.contribution.pay_gap_needed",
              "value": null
            }
          ]
        }
      },
      {
        "row_id": "row_2_intersects",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.social.paid_months_in_year"
                },
                null
              ]
            },
            {
              "intersects": [
                {
                  "var": "user.social.paid_months_in_year"
                },
                {
                  "var": "params.T-SH-PAY-GAP-MONTHS"
                }
              ]
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.contribution.pay_gap_needed",
              "value": true
            },
            {
              "type": "emit_warning",
              "value": {
                "warning_id": "W-PAY-GAP",
                "text": "你的缴费月份包含可能需要补差的月份（常见7-8月，视社平/基数发布时间）。请关注随申办/税务通知并及时补差，避免影响后续扣费。"
              }
            }
          ]
        }
      },
      {
        "row_id": "row_3_not_needed",
        "when": {
          "and": [
            {
              "!=": [
                {
                  "var": "user.social.paid_months_in_year"
                },
                null
              ]
            },
            {
              "!": {
                "intersects": [
                  {
                    "var": "user.social.paid_months_in_year"
                  },
                  {
                    "var": "params.T-SH-PAY-GAP-MONTHS"
                  }
                ]
              }
            }
          ]
        },
        "then": {
          "actions": [
            {
              "type": "set",
              "path": "calc.contribution.pay_gap_needed",
              "value": false
            }
          ]
        }
      }
    ]
  },
  "outputs": [
    {
      "key": "calc.contribution.pay_gap_needed",
      "type": "boolean"
    },
    {
      "key": "calc.warnings",
      "type": "array"
    }
  ],
  "examples": [
    {
      "name": "缴费月份包含7 -> 需要补差提醒",
      "input": {
        "user": {
          "social": {
            "paid_months_in_year": [
              6,
              7,
              8
            ]
          }
        }
      },
      "expected": {
        "calc": {
          "contribution": {
            "pay_gap_needed": true
          }
        }
      }
    }
  ],
  "evidence": [],
  "operation": "add"
}
